const insertErrorLog = async (data = {}) => {
    try {
        const pool = flow.get('pg_pool');
        if (!pool) {
            node.error("PostgreSQL pool not initialized");
            return null;
        };

        const {
            code = null,
            message = null,
            context = null
        } = data;

        const res = await pool.query(
            `INSERT INTO error_logs
             (code, message, context)
             VALUES ($1, $2, $3)`,
            [code, message, context ? JSON.stringify(context) : null]
        );

        msg.payload = res.rows;
        return msg;
    } catch (err) {
        msg.payload = {
            status: 'error',
            message: err.message,
            code: err.code,
            originalData: data
        };

        node.error('Failed to insert log', msg);
        return msg;
    }
};

flow.set('insertErrorLog', insertErrorLog);
return msg;

